<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { busDiagnostics, type BusSettings, type Delivery } from '../simulation/serialBus'
import { baudRates, type Switcher } from '../simulation/switcher'
const props = defineProps<{ settings: BusSettings; switchers: Switcher[]; deliveries: Delivery[]; serialConnected: boolean; pending: number; command: string }>()
const emit = defineEmits<{ baud: [value: number]; cameraBaud: [value: number]; fault: [kind: string, switcherId: string] }>()
const diagnostics = computed(() => busDiagnostics(props.settings, props.switchers))
const targetId = ref(props.switchers.find(item => item.enabled)?.id ?? '')
watch(() => props.switchers.map(item => `${item.id}:${item.enabled}`), () => {
  if (!props.switchers.some(item => item.enabled && item.id === targetId.value)) targetId.value = props.switchers.find(item => item.enabled)?.id ?? ''
})
const devices = computed(() => [...(props.settings.cameras ?? [{ id: 'camera', name: 'PTZ camera', address: props.settings.cameraAddress, baudRate: props.settings.cameraBaudRate }]).map(item => ({ ...item, enabled: true })), ...props.switchers])
function deliveryClass(result: string) { return result === 'Rejected' ? 'error' : result === 'Baud mismatch' ? 'warning' : ['Address filtered', 'Disabled', 'Ignored opcode', 'Not simulated', 'No preset'].includes(result) ? 'neutral' : 'success' }
</script>

<template>
  <section class="panel bus-panel">
    <div class="panel-heading"><h2><span class="small-icon">⌁</span> Shared serial bus</h2><span class="bus-format">ONE STREAM · 8N1</span></div>
    <div class="bus-content">
      <div class="bus-topline"><div><strong>Every device sees the same bytes.</strong><p>Address and baud rate decide who can receive them; the opcode decides what each device does.</p></div><label>Bus baud rate<select :value="settings.baudRate" :disabled="serialConnected" aria-label="Shared bus baud rate" @change="emit('baud', Number(($event.target as HTMLSelectElement).value))"><option v-for="rate in baudRates" :key="rate" :value="rate">{{ rate }}</option></select></label><label>Camera baud rate<select :value="settings.cameraBaudRate" aria-label="Camera baud rate" @change="emit('cameraBaud', Number(($event.target as HTMLSelectElement).value))"><option v-for="rate in baudRates" :key="rate" :value="rate">{{ rate }}</option></select></label></div>
      <div class="bus-device-list"><div v-for="device in devices" :key="device.id" class="bus-device" :class="{ 'device-off': !device.enabled, mismatch: device.enabled && device.baudRate !== settings.baudRate }"><i class="status-dot" :class="{ offline: !device.enabled || device.baudRate !== settings.baudRate }"></i><strong>{{ device.name }}</strong><code>{{ device.address }}</code><span>{{ device.baudRate }} baud{{ device.enabled ? '' : ' · disabled' }}</span></div></div>
      <div v-if="diagnostics.length" class="bus-diagnostics" role="status"><p v-for="(diagnostic, i) in diagnostics" :key="i"><span>!</span>{{ diagnostic.message }}</p></div><p v-else class="bus-healthy"><span>✓</span> Unique addresses · baud rates match</p>
      <div v-if="pending" class="inline-warning">{{ pending }} byte(s) awaiting completion on the shared bus.</div>
      <details class="bus-delivery" :open="deliveries.some(item => ['Routed', 'Rejected', 'Baud mismatch'].includes(item.result))"><summary>Delivery of selected packet<span>{{ command || 'Waiting for a packet' }}</span></summary><div v-if="deliveries.length" class="delivery-table"><div v-for="item in deliveries" :key="item.id" class="delivery-row"><strong>{{ item.name }} <code>{{ item.address }}</code></strong><span class="result-tag" :class="deliveryClass(item.result)">{{ item.result }}</span><span>{{ item.detail }}</span></div></div><p v-else class="bus-waiting">{{ command ? 'No complete frame was delivered to devices. See the byte diagnostics below.' : "Send a command to inspect each device's response." }}</p></details>
      <details class="fault-lab"><summary>Interference & recovery<span>Inject faults into the shared stream</span></summary><div class="fault-content"><label>Target switcher<select v-model="targetId" aria-label="Fault injection switcher"><option v-if="!targetId" value="">Add an enabled switcher first</option><option v-for="item in switchers.filter(item => item.enabled)" :key="item.id" :value="item.id">{{ item.name }} · {{ item.address }}</option></select></label><div class="fault-buttons"><button class="button secondary" :disabled="!targetId" @click="emit('fault', 'mixed', targetId)">Mixed camera + routes</button><button class="button secondary" :disabled="!targetId" @click="emit('fault', 'checksum', targetId)">Bad checksum</button><button class="button secondary" :disabled="!targetId" @click="emit('fault', 'dropped', targetId)">Dropped byte</button><button class="button secondary" :disabled="!targetId" @click="emit('fault', 'interleaved', targetId)">Interleaved senders</button></div><p>These send real test bytes through the same parser, ending with a clean camera stop. Rejected frames keep the previous route. Address conflicts are tested by configuring devices with the same address.</p><p class="fault-note">Byte-level simulation: baud mismatches are ignored, and corruption is injected explicitly. Electrical noise and device replies are not modeled.</p></div></details>
    </div>
  </section>
</template>

<style scoped>
