ign-items:center;border-top:1px solid #243440;padding:10px 0;font-size:10px}.delivery-row strong{font-weight:500;color:#a7c4d4;overflow:hidden;text-overflow:ellipsis}.delivery-row code{font-size:9px;color:#668a9d;margin-left:8px}.delivery-row>span:last-child{color:#7898ab;font-size:9px}.bus-waiting{color:#688999;font-size:10px;margin:0 0 15px}.fault-content>label{display:flex;gap:12px;align-items:center;color:#94b0c0;font-size:10px}.fault-content select{font-size:10px;padding:8px;max-width:70%}.fault-buttons{display:flex;flex-wrap:wrap;gap:10px;margin:15px 0}.fault-buttons .button{font-size:10px}.fault-content p{font-size:9px;color:#83a2b3;line-height:1.9;margin:10px 0}.fault-content .fault-note{color:#657f91}
@media(max-width:760px){.bus-topline{flex-wrap:wrap;gap:15px}.bus-topline>div{min-width:100%}.delivery-row{grid-template-columns:1fr 110px;gap:9px}.delivery-row>span:last-child{grid-column:1/-1}.bus-device{flex-wrap:wrap}.bus-content details summary>span{float:none;display:block;max-width:100%;padding-left:15px;margin-top:6px}.bus-format{font-size:7px;letter-spacing:0}}
</style>
